import { test } from '@playwright/test'
import { opGoto, opClick, opFill, opPress, opSeen } from './prims'

test('@journey:suite @smoke Open contact form in two tabs and submit in both', async ({ page }) => {
  await opGoto(page, '/contact')
  await opFill(page, 'Name', 'Multi-tab User')
  await opFill(page, 'Email', 'tab1@example.com')
  await opClick(page, 'button', 'Send')
  await opFill(page, 'Email', 'tab2@example.com')
  await opClick(page, 'button', 'Send')
  await opSeen(page, 'main', 'Thank you. We will be in touch shortly.')
})
